        System.out.println("empty read()=" + c + " lineNumber=" + call(cls,r,"getLineNumber") + " position=" + call(cls,r,"getPosition") + " lastChar=" + call(cls,r,"getLastChar"));
        // read again
        c = (int) call(cls, r, "read");
        System.out.println("empty read() again =" + c + " lineNumber=" + call(cls,r,"getLineNumber") + " position=" + call(cls,r,"getPosition"));

        // Test 2: "abc" no newline
        r = ctor.newInstance(new StringReader("abc"));
        for (int i=0;i<3;i++) call(cls,r,"read");
        System.out.println("abc after 3 reads lineNumber=" + call(cls,r,"getLineNumber"));
        c = (int) call(cls,r,"read");
        System.out.println("abc EOF read=" + c + " lineNumber=" + call(cls,r,"getLineNumber") + " position=" + call(cls,r,"getPosition"));

        // Test 3: "abc\n"
        r = ctor.newInstance(new StringReader("abc\n"));
        for (int i=0;i<4;i++) call(cls,r,"read");
        System.out.println("abc\\n after 4 reads lineNumber=" + call(cls,r,"getLineNumber"));
        c = (int) call(cls,r,"read");
        System.out.println("abc\\n EOF read=" + c + " lineNumber=" + call(cls,r,"getLineNumber"));

        // Test 4: initial state
        r = ctor.newInstance(new StringReader("xyz"));
        System.out.println("initial lastChar=" + call(cls,r,"getLastChar") + " lineNumber=" + call(cls,r,"getLineNumber") + " position=" + call(cls,r,"getPosition"));

        // Test 5: peek doesn't advance
        r = ctor.newInstance(new StringReader("hi"));
        Method peek = cls.getMethod("peek");
        int p = (int) peek.invoke(r);
        System.out.println("peek=" + (char)p + " lastChar after peek=" + call(cls,r,"getLastChar") + " position=" + call(cls,r,"getPosition"));
        c = (int) call(cls,r,"read");
        System.out.println("read after peek=" + (char)c);

        // Test 6: readLine
        r = ctor.newInstance(new StringReader("line1\r\nline2\nline3"));
        Method readLine = cls.getMethod("readLine");
        System.out.println("readLine1=" + readLine.invoke(r) + " lineNumber=" + call(cls,r,"getLineNumber"));
        System.out.println("readLine2=" + readLine.invoke(r) + " lineNumber=" + call(cls,r,"getLineNumber"));
        System.out.println("readLine3=" + readLine.invoke(r) + " lineNumber=" + call(cls,r,"getLineNumber"));
        System.out.println("readLine4=" + readLine.invoke(r));

        // Test 7: mark/reset
        r = ctor.newInstance(new StringReader("0123456789"));
        call(cls,r,"read"); call(cls,r,"read");
        Method mark = cls.getMethod("mark", int.class);
        mark.invoke(r, 10);
        call(cls,r,"read"); call(cls,r,"read");
        System.out.println("before reset position=" + call(cls,r,"getPosition") + " lastChar=" + call(cls,r,"getLastChar"));
        Method reset = cls.getMethod("reset");
        reset.invoke(r);
        System.out.println("after reset position=" + call(cls,r,"getPosition") + " lastChar=" + call(cls,r,"getLastChar"));
        c = (int) call(cls,r,"read");
        System.out.println("read after reset=" + (char)c);

        // Test 8: close sets lastChar EOF
        r = ctor.newInstance(new StringReader("abc"));
        call(cls,r,"read");
        Method close = cls.getMethod("close");
        close.invoke(r);
        System.out.println("after close lastChar=" + call(cls,r,"getLastChar"));

        // Test 9: bulk read
        r = ctor.newInstance(new StringReader("hello\nworld"));
        Method readBuf = cls.getMethod("read", char[].class, int.class, int.class);
        char[] buf = new char[20];
        int n = (int) readBuf.invoke(r, buf, 0, 20);
        System.out.println("bulk read n=" + n + " content=" + new String(buf,0,n) + " lineNumber=" + call(cls,r,"getLineNumber") + " position=" + call(cls,r,"getPosition") + " lastChar=" + call(cls,r,"getLastChar"));
        n = (int) readBuf.invoke(r, buf, 0, 20);
        System.out.println("bulk read again n=" + n + " position=" + call(cls,r,"getPosition"));

        // Test 10: read(buf,offset,0)
        r = ctor.newInstance(new StringReader("hello"));
        n = (int) readBuf.invoke(r, buf, 0, 0);
        System.out.println("read len 0 n=" + n + " lastChar=" + call(cls,r,"getLastChar") + " position=" + call(cls,r,"getPosition"));
    }

    static Object call(Class<?> cls, Object obj, String name) throws Exception {
        Method m = cls.getDeclaredMethod(name);
        m.setAccessible(true);
        return m.invoke(obj);
    }
}
